package com.example.application_service.entity;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="application_status_histories") public class ApplicationStatusHistory {@Id private UUID id;@Column(name="application_id")private UUID applicationId;@Enumerated(EnumType.STRING)@Column(name="from_status")private ApplicationStatus fromStatus;@Enumerated(EnumType.STRING)@Column(name="to_status")private ApplicationStatus toStatus;@Column(name="changed_by")private UUID changedBy;private String note;@Column(name="created_at")private Instant createdAt;protected ApplicationStatusHistory(){}public ApplicationStatusHistory(UUID applicationId,ApplicationStatus from,ApplicationStatus to,UUID actor,String note){id=UUID.randomUUID();this.applicationId=applicationId;fromStatus=from;toStatus=to;changedBy=actor;this.note=note==null?null:note.trim();createdAt=Instant.now();}public UUID getId(){return id;}public UUID getApplicationId(){return applicationId;}public ApplicationStatus getFromStatus(){return fromStatus;}public ApplicationStatus getToStatus(){return toStatus;}public UUID getChangedBy(){return changedBy;}public String getNote(){return note;}public Instant getCreatedAt(){return createdAt;}}
